<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Accessor\MessageTargetAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the MessageTargetAccessor trait.
 *
 * Covers null default, string/VO assignment via withTarget,
 * getTarget/target accessors, and isTargetChanged with/without original.
 */
class MessageTargetAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withTarget creates a new instance with the Target set
     * from a string value, and getTarget returns the primitive string.
     */
    public function testWithTargetFromString(): void
    {
        // Arrange
        $holder = new ImplWithMessageTargetAccessorUnitTest();

        // Act
        $result = $holder->withTarget('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getTarget());
    }
    /**
     * Asserts that withtarget has access to the value object
     * from a string value, and getTarget returns the primitive string.
     */
    public function testWithTargetFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithMessageTargetAccessorUnitTest();

        // Act
        $result = $holder->withTarget('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->target()->value());
    }
    public function testChangedTarget(): void
    {
        // Arrange
        $holder = new ImplWithMessageTargetAccessorUnitTest()->withTarget('one');
        $original = $holder->withTarget('one');
        $same = $holder->withTarget('one');
        $modified = $holder->withTarget('other');

        // Act
        $withSame = $original->isTargetChanged($same);
        $withDiferent = $original->isTargetChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithMessageTargetAccessorUnitTest
{
    use MessageTargetAccessor;
}
